import {
    type BasicContext,
    type BasicPluginContextValue,
    type ContextLevel,
    type FullPluginContextValue,
    PluginProvider,
    type PluginProviderProps,
    type Theme,
    usePluginContext,
} from '@weavix/sdk-react';
import type {
    GetDataResultMap,
    HandlerFunction,
    Handlers,
    SlotContextMap,
} from '@weavix/tracker-plugin-sdk';
import { type ReactNode, createContext, useContext, useMemo } from 'react';

/** Строковые ключи слота (для индексных типов без `symbol` в keyof). */
type TrackerSlotKey = Extract<keyof SlotContextMap, string>;

/**
 * Сигнатура registerHandler: для 'getData' тип handler зависит от слота (GetDataResultMap[TSlot]).
 */
export type RegisterHandlerFunction<TSlot extends TrackerSlotKey> = <TKey extends keyof Handlers>(
    methodName: TKey,
    handler: TKey extends 'getData'
        ? TSlot extends keyof GetDataResultMap
            ? () => GetDataResultMap[TSlot]
            : never
        : HandlerFunction<TKey>,
) => void;

/**
 * Контекст плагина при contextLevel = 'basic'.
 * slotContext содержит только entityId.
 */
export interface BasicTrackerPluginContextValue<TSlot extends TrackerSlotKey = TrackerSlotKey> {
    /** Текущая тема хоста. Обновляется реактивно при получении theme.changed. */
    theme: Theme | undefined;
    /** Текущий язык хоста. Обновляется реактивно при получении language.changed. */
    language: string | undefined;
    /** Сервис, в котором открылся плагин. */
    service: string;
    /** Id пользователя. */
    userId?: string;
    /** Id организации. */
    orgId?: string;
    /** Это ятим? */
    isYateam?: boolean;
    /** Включена ли Орбита */
    isOrbita?: boolean;
    /** Origin родительского окна (хоста). */
    origin: string;
    /** Слот, в котором открыт плагин. */
    slot: TSlot;
    /** URL внутри плагина. */
    innerUrl: string;
    /** Query-параметры плагина */
    queryParams: Record<string, string>;
    /** Контекст страницы — только entityId при basic уровне. */
    slotContext: BasicContext | undefined;
    /** Регистрация обработчика для ответов на запросы хоста. */
    registerHandler: RegisterHandlerFunction<TSlot>;
    /** Уровень контекста, объявленный в манифесте. */
    contextLevel: 'basic';
}

/**
 * Контекст плагина при contextLevel = 'full'.
 * slotContext содержит полный объект слота (Issue, TriggerContext и т.д.).
 */
export interface FullTrackerPluginContextValue<TSlot extends TrackerSlotKey = TrackerSlotKey> {
    /** Текущая тема хоста. Обновляется реактивно при получении theme.changed. */
    theme: Theme | undefined;
    /** Текущий язык хоста. Обновляется реактивно при получении language.changed. */
    language: string | undefined;
    /** Сервис, в котором открылся плагин. */
    service: string;
    /** Id пользователя. */
    userId?: string;
    /** Id организации. */
    orgId?: string;
    /** Это ятим? */
    isYateam?: boolean;
    /** Включена ли Орбита */
    isOrbita?: boolean;
    /** Origin родительского окна (хоста). */
    origin: string;
    /** Слот, в котором открыт плагин. */
    slot: TSlot;
    /** URL внутри плагина. */
    innerUrl: string;
    /** Query-параметры плагина */
    queryParams: Record<string, string>;
    /** Контекст страницы — полный объект слота при full уровне. */
    slotContext: SlotContextMap[TSlot] | undefined;
    /** Регистрация обработчика для ответов на запросы хоста. */
    registerHandler: RegisterHandlerFunction<TSlot>;
    /** Уровень контекста, объявленный в манифесте. */
    contextLevel: 'full';
}

type TrackerServiceContextValue = {
    registerHandler: RegisterHandlerFunction<TrackerSlotKey>;
};

const TrackerServiceContext = createContext<TrackerServiceContextValue | null>(null);

/**
 * Сервисный слой поверх {@link PluginProvider}: типизированный под Tracker `registerHandler`
 * и обязательная обёртка для {@link useTrackerPluginContext}.
 */
function TrackerPluginServiceLayer({ children }: { children: ReactNode }) {
    const { registerHandler: baseRegisterHandler } = usePluginContext('basic');

    const typedRegisterHandler = useMemo<RegisterHandlerFunction<TrackerSlotKey>>(() => {
        return ((methodName, handler) =>
            baseRegisterHandler(
                methodName as string,
                handler as (...args: unknown[]) => unknown,
            )) as RegisterHandlerFunction<TrackerSlotKey>;
    }, [baseRegisterHandler]);

    const value = useMemo(
        () => ({ registerHandler: typedRegisterHandler }),
        [typedRegisterHandler],
    );

    return (
        <TrackerServiceContext.Provider value={value}>{children}</TrackerServiceContext.Provider>
    );
}

/**
 * Обёртка над стандартным {@link PluginProvider}: инициализация и общий контракт хоста в SDK,
 * поверх — трекер-специфичный контекст (типизированный `registerHandler` и проверка для
 * {@link useTrackerPluginContext}).
 */
export function TrackerPluginProvider(props: PluginProviderProps) {
    return (
        <PluginProvider {...props}>
            <TrackerPluginServiceLayer>{props.children}</TrackerPluginServiceLayer>
        </PluginProvider>
    );
}

export type TrackerPluginProviderProps = PluginProviderProps;

/**
 * Хук для получения темы, языка, слота и контекста слота из TrackerPluginProvider.
 */
export function useTrackerPluginContext(): {
    [K in TrackerSlotKey]: BasicTrackerPluginContextValue<K>;
}[TrackerSlotKey];
export function useTrackerPluginContext(level: 'basic'): {
    [K in TrackerSlotKey]: BasicTrackerPluginContextValue<K>;
}[TrackerSlotKey];
export function useTrackerPluginContext(level: 'full'): {
    [K in TrackerSlotKey]: FullTrackerPluginContextValue<K>;
}[TrackerSlotKey];
export function useTrackerPluginContext<TSlot extends TrackerSlotKey>(
    level?: 'basic',
): BasicTrackerPluginContextValue<TSlot>;
export function useTrackerPluginContext<TSlot extends TrackerSlotKey>(
    level: 'full',
): FullTrackerPluginContextValue<TSlot>;
export function useTrackerPluginContext(
    level: ContextLevel = 'basic',
): BasicTrackerPluginContextValue | FullTrackerPluginContextValue {
    const base = usePluginContext(level as 'basic') as
        | BasicPluginContextValue
        | FullPluginContextValue;
    const service = useContext(TrackerServiceContext);
    if (!service) {
        throw new Error(
            'useTrackerPluginContext must be used within TrackerPluginProvider (Tracker service layer). ' +
                'Use PluginProvider only with usePluginContext, or wrap the app with TrackerPluginProvider.',
        );
    }

    const slot = base.slot as TrackerSlotKey;

    if (level === 'full') {
        return {
            ...base,
            slot,
            registerHandler: service.registerHandler as RegisterHandlerFunction<typeof slot>,
            slotContext: base.slotContext as SlotContextMap[typeof slot] | undefined,
        } as FullTrackerPluginContextValue;
    }

    return {
        ...base,
        slot,
        registerHandler: service.registerHandler as RegisterHandlerFunction<typeof slot>,
    } as BasicTrackerPluginContextValue;
}

export { isInternalUrl } from '@weavix/sdk-react';
